import { includedInSuccessRate } from "../constants.js";
export const getSuccessRateTotal = (statistic) => Array.from(includedInSuccessRate).reduce((total, status) => total + (statistic[status] ?? 0), 0);
export const getSuccessRate = (statistic) => {
    const total = getSuccessRateTotal(statistic);
    return total > 0 ? (statistic.passed ?? 0) / total : 0;
};
